from lib import *
S = SS('q11')
steps = [
    step("最常见的“延迟消息”做法不需要插件:把消息发进一个没人消费的队列,给它设 TTL,过期后靠死信交换机转到真正被消费的队列。队列级 x-message-ttl = 1000 ms,隔 300 ms 发 3 条,发送时刻 0、304、612 ms,到达死信队列的时刻是 1002、1307、1614 ms,实际延迟分别是 1002、1003、1002 ms——误差只有几毫秒。", t=tl(S(1)), mark=lidx(S(1), '实际延迟'), done=lidx(S(1), '发送时刻'), kv=KV([['做法', '延迟队列(无消费者)+ TTL + 死信'], ['精度', '延迟误差约 +2 ms'], ['无需插件', '']], ['做法'])),
    step("队头阻塞:单条消息各自设 expiration 时,队列只看队头。先发 expiration=3000 ms 的 long,再发 expiration=300 ms 的 short:short 并没有在 300 ms 时死信,而是和 long 一起在 3004 ms 才出现(classic 队列),quorum 队列同样是 3006 ms。后面的短 TTL 被前面的长 TTL 挡住了。", t=tl(S(2)), mark=lidx(S(2), 'classic 队列', 'quorum 队列'), done=lidx(S(2), 'classic 队列'), b=bars([['short(300ms) 实际', 3004, '3004 ms'], ['short(300ms) 期望', 300, '300 ms']], 3004, mark=[0], done=[1]), kv=KV([['per-message TTL', '只在队头检查'], ['结果', '短 TTL 被长 TTL 挡住'], ['classic / quorum', '都一样']], ['per-message TTL'])),
    step("反过来先发 short(300 ms)再发 long(3000 ms):short 在 303 ms 就死信,long 在 3003 ms,各自准时。所以顺序对就没有问题——但谁也保证不了发布顺序,不能靠这个。", t=tl(S(3)), mark=lidx(S(3), '到达死信队列'), done=lidx(S(3), '到达死信队列'), kv=KV([['短在前', '各自准时'], ['结论', '只对 TTL 单调递增的消息成立']], ['结论'])),
    step("避开阻塞的办法:一种延迟一个队列,队列级 TTL。300、1000、2000 ms 三个延迟队列,交错发布 6 条 a(2000)、b(300)、c(1000)、d(300)、e(2000)、f(1000),到达死信队列的时刻是 b、d 在 303 ms,c、f 在 1003 ms,a、e 在 2005 ms——各按各的延迟准时走。代价是延迟档位要事先定好。", t=tl(S(4)), mark=lidx(S(4), '几乎同时发出'), done=lidx(S(4), '几乎同时发出'), b=bars([['300 ms 队列', 303, '303 ms'], ['1000 ms 队列', 1003, '1003 ms'], ['2000 ms 队列', 2005, '2005 ms']], 2005, mark=[0, 1, 2]), kv=KV([['一档一队列', '队列级 TTL,先进先出 = 先过期'], ['代价', '延迟档位固定'], ['任意延迟', '需要插件或自己实现']], ['一档一队列'])),
    step("精度:队列 TTL=500 ms,每隔 50 ms 发一条共 200 条,收到 200 条,延迟(到达 − 发送)最小 501、p50 503、p99 506、最大 506 ms——目标 500,误差在 6 ms 以内。这里每条消息很小、队列几乎是空的;队列里压了很多消息、broker 很忙时精度没有测。", t=tl(S(5)), mark=lidx(S(5), '收到 200 条'), done=lidx(S(5), '收到 200 条'), b=bars([['min', 501, '501 ms'], ['p50', 503, '503 ms'], ['p99', 506, '506 ms'], ['max', 506, '506 ms']], 506, mark=[2]), kv=KV([['目标', '500 ms'], ['实测', '501~506 ms'], ['条件', '队列几乎空、消息小']], ['实测'])),
    step("延迟消息躺在队列里的这段时间是有成本的:往 TTL=60 秒的队列里塞 50000 条 1 KB 的持久化消息,队列里有 50000 条、message_bytes 48.8 MiB;队列进程自己的内存只有 0.7 MiB(消息体在磁盘上,这是 4.x 经典队列的特点)。没有单独的“延迟存储”,延迟越长、量越大,队列里躺的数据就越多。", t=tl(S(6)), mark=lidx(S(6), 'big.q'), done=lidx(S(6), '队列进程自己占的内存'), kv=KV([['50000 条 × 1 KB', 'message_bytes 48.8 MiB'], ['队列进程内存', '0.7 MiB'], ['含义', '数据在磁盘,但要占一段时间']], ['50000 条 × 1 KB'])),
]
A = mkartq('q11', 11, 'RabbitMQ,延迟消息,TTL,死信,队头阻塞,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上实测 TTL + 死信做延迟消息:队列级 TTL 1000 ms 的延迟误差约 2 ms;单条消息 expiration 不同时,短的被队头的长的挡住(300 ms 的拖到 3004 ms),classic 和 quorum 都一样;一种延迟一个队列可避开阻塞;TTL 500 ms 的延迟 501~506 ms;50000 条 1 KB 延迟消息占 48.8 MiB。',
    '没有插件时,RabbitMQ 做延迟消息靠“TTL + 死信”。这样做能准到多少毫秒?给每条消息单独设 expiration 为什么会翻车?延迟队列要怎么设计,消息躺在里面占多少资源?这篇都量一遍。',
    [('+2 ms', '队列 TTL=1000 ms 时,消息到达死信队列的实际延迟(1002 ms)'), ('3004 ms', '先发 3000 ms 再发 300 ms 的消息时,后者实际死信的时刻——被队头挡住'), ('48.8 MiB', '50000 条 1 KB 的延迟消息躺在队列里的数据量,队列进程自己只占 0.7 MiB')],
    [('做法', '<p>消息发到一个没有消费者的延迟队列,队列设 <code>x-message-ttl</code> 和 <code>x-dead-letter-exchange</code>;过期后死信被转到真正的业务队列。实测延迟比设定值只多几毫秒。</p>'),
     ('队头阻塞', '<p>队列只在队头检查是否过期。每条消息单独设 <code>expiration</code> 时,TTL 短的排在 TTL 长的后面,就要等前面的先过期。classic 和 quorum 队列都是如此。</p>'),
     ('顺序', '<p>如果先短后长,各自准时;但发布顺序无法保证,所以不能依赖。</p>'),
     ('一档一队列', '<p>每种延迟时间建一个队列、用队列级 TTL,同一队列里 TTL 相同,先进先出就是先过期,没有阻塞。代价是延迟时间只能取预先定义的几档。</p>'),
     ('精度', '<p>队列 TTL=500 ms 时延迟实测 501~506 ms。队列压满消息、broker 忙时的精度没有测。</p>'),
     ('成本', '<p>延迟期间消息一直占着队列(磁盘和索引),量大、延迟长的场景要算上这部分。</p>')],
    steps,
    [ENV_Q + '。延迟精度用 perf_counter 计发送与到达的时刻,到达时刻由死信队列上的消费者回调记录;第五节发 200 条(每隔 50 ms),第六节 50000 条 1 KB 的持久化消息,等 2 秒后用 rabbitmqctl list_queues 读 messages、memory、message_bytes',
     '没有验证:社区的延迟消息交换机插件(rabbitmq_delayed_message_exchange,Homebrew 的 4.3.6 里没有这个插件);更长的延迟(分钟、小时)下队列的行为;broker 重启后延迟消息 TTL 的重新计时;队列里堆很多消息时过期扫描的精度;quorum 队列上 TTL 过期的精度(只看了队头阻塞)'],
    '延迟消息')
